@Component("asset-subscriber")
public class AssetSubscriber extends BaseSubscriber {

	public AssetSubscriber() {
	}
	
    public SubscriptionQueryResult<List<Asset>, Asset> assetSubscribe() {
        return queryGateway
                .subscriptionQuery(new FindAllAssetQuery(), 
                		ResponseTypes.multipleInstancesOf(Asset.class),
                		ResponseTypes.instanceOf(Asset.class));
    }

    public SubscriptionQueryResult<Asset, Asset> assetSubscribe(@DestinationVariable UUID assetId) {
        return queryGateway
                .subscriptionQuery(new FindAssetQuery(new LoadAssetFilter(assetId)), 
                		ResponseTypes.instanceOf(Asset.class),
                		ResponseTypes.instanceOf(Asset.class));
    }





}

